//! Authored API assembly bootstrap for sdkwork-order.
//! Route inventory is regenerated by `pnpm api:assembly:materialize`.
//!
//! Multi-surface merges mount shared infrastructure routes once at the assembly layer
//! so `/healthz`, `/livez`, `/readyz`, and `/metrics` are not duplicated per surface.

use std::sync::Arc;

use axum::Router;
use sdkwork_database_spi::{DefaultDatabaseModule, SpiError};
use sdkwork_database_sqlx::DatabasePool;
use sdkwork_order_service_host::OrderServiceHost;
pub use sdkwork_web_bootstrap::ApiAssemblyContribution;
use sdkwork_web_bootstrap::{ContractFallbackConfig, ReadinessCheck, ReadinessFuture, WebModule};
use sdkwork_web_core::HttpRouteManifest;

pub type ApiAssembly = ApiAssemblyContribution;

pub struct BusinessRouterAssembly {
    pub router: Router,
}

pub struct OrderAssemblyContract;

#[derive(Clone)]
struct OrderReadiness {
    pool: DatabasePool,
}

impl ReadinessCheck for OrderReadiness {
    fn check(&self) -> ReadinessFuture<'_> {
        let pool = self.pool.clone();
        Box::pin(async move {
            match pool.test_connection().await {
                Ok(true) => Ok(()),
                Ok(false) => Err("order database readiness query returned no row".to_owned()),
                Err(error) => Err(format!("order database readiness check failed: {error}")),
            }
        })
    }
}

impl OrderAssemblyContract {
    pub async fn from_database_pool(pool: DatabasePool) -> Result<Self, String> {
        OrderServiceHost::from_database_pool(pool).await?;
        Ok(Self)
    }

    pub fn database_module() -> Result<DefaultDatabaseModule, SpiError> {
        sdkwork_order_database_host::database_module()
    }

    pub fn app_route_manifest() -> HttpRouteManifest {
        sdkwork_routes_order_app_api::http_route_manifest::app_route_manifest()
    }

    pub fn contract_fallback_config() -> ContractFallbackConfig {
        let mut config = ContractFallbackConfig::from_manifest(&Self::app_route_manifest());
        let backend = ContractFallbackConfig::from_manifest(
            &sdkwork_routes_order_backend_api::http_route_manifest::backend_route_manifest(),
        );
        config.manifest_paths.extend(backend.manifest_paths);
        config
    }
}

/// Owns the in-process background workers (expiration scheduler, payment
/// compensation worker) so the standalone gateway can stop them during
/// graceful shutdown instead of letting the runtime drop cancel them at an
/// arbitrary await point.
#[derive(Default)]
pub struct OrderRuntimeWorkers {
    handles: Vec<tokio::task::JoinHandle<()>>,
}

impl OrderRuntimeWorkers {
    /// Aborts every worker loop. Safe to call multiple times; each pass is
    /// transactional in the database and PSP interactions are idempotent,
    /// so an abort mid-pass is recovered by the next process run.
    pub fn shutdown(&mut self) {
        for handle in self.handles.drain(..) {
            handle.abort();
        }
    }
}

/// Composes the Order API module (app + backend surfaces) with runtime workers
/// started and owned by the caller.
///
/// This is the ONE routing composition: both the standalone gateway and the
/// embedded cloud gateway reach it, and it delegates to
/// [`assemble_api_router_without_workers`] so the route set can never diverge
/// between "who starts the workers" variants.
pub async fn assemble_api_router(host: Arc<OrderServiceHost>) -> Result<ApiAssembly, String> {
    start_runtime_workers(&host).await;
    assemble_api_router_without_workers(host).await
}

/// Same as [`assemble_api_router`] but also hands back the background worker
/// handles for lifecycle-controlled deployments (the standalone gateway).
pub async fn assemble_api_router_with_runtime(
    host: Arc<OrderServiceHost>,
) -> Result<(ApiAssembly, OrderRuntimeWorkers), String> {
    let workers = start_runtime_workers(&host).await;
    let assembly = assemble_api_router_without_workers(host).await?;
    Ok((assembly, workers))
}

async fn assemble_api_router_without_workers(
    host: Arc<OrderServiceHost>,
) -> Result<ApiAssembly, String> {
    let router = Router::new()
        .merge(sdkwork_routes_order_app_api::gateway_mount(host.clone()).await)
        .merge(sdkwork_routes_order_backend_api::gateway_mount(host.clone()).await);
    let mut routes = Vec::new();
    routes.extend_from_slice(sdkwork_routes_order_app_api::gateway_route_manifest().routes());
    routes.extend_from_slice(sdkwork_routes_order_backend_api::gateway_route_manifest().routes());
    ApiAssemblyContribution::from_manifest(
        "sdkwork-order",
        "SDKWork Order API",
        router,
        HttpRouteManifest::from_owned_routes(routes),
        Vec::new(),
        Arc::new(OrderReadiness {
            pool: host.database_pool().clone(),
        }),
    )
}

pub async fn assemble_api_router_with_pool(pool: DatabasePool) -> Result<ApiAssembly, String> {
    let host = Arc::new(OrderServiceHost::from_database_pool(pool).await?);
    assemble_api_router(host).await
}

pub async fn assemble_backend_business_router(
    host: Arc<OrderServiceHost>,
) -> BusinessRouterAssembly {
    BusinessRouterAssembly {
        router: sdkwork_routes_order_backend_api::gateway_mount(host).await,
    }
}

/// Builds the raw Order App API for a gateway-owned Web Framework layer.
pub async fn assemble_app_api_contribution() -> Result<ApiAssemblyContribution, String> {
    let host = Arc::new(OrderServiceHost::from_env().await?);
    start_runtime_workers(&host).await;
    assemble_app_api_contribution_with_host(host)
}

pub async fn assemble_app_api_contribution_with_pool(
    pool: DatabasePool,
) -> Result<ApiAssemblyContribution, String> {
    let host = Arc::new(OrderServiceHost::from_database_pool(pool).await?);
    start_runtime_workers(&host).await;
    assemble_app_api_contribution_with_host(host)
}

async fn start_runtime_workers(host: &Arc<OrderServiceHost>) -> OrderRuntimeWorkers {
    let mut workers = OrderRuntimeWorkers::default();
    if let Some(handle) = sdkwork_order_service_host::spawn_order_expiration_scheduler(host.clone())
    {
        workers.handles.push(handle);
    }
    if let Some(handle) =
        sdkwork_order_service_host::spawn_payment_compensation_worker(host.clone())
    {
        workers.handles.push(handle);
    }
    if let Some(handle) =
        sdkwork_order_service_host::spawn_course_entitlement_relay(host.clone()).await
    {
        workers.handles.push(handle);
    }
    if let Some(handle) = spawn_cart_abandonment_sweep(host) {
        workers.handles.push(handle);
    }
    workers
}

/// Expires the buyer carts nobody touched for `SDKWORK_ORDER_CART_IDLE_DAYS`
/// days (default 30), one bounded batch per tick.
///
/// Without this the unique "one active cart per buyer" index would keep a
/// months-old cart occupying the slot: the buyer's next add would land in a
/// stale basket instead of a fresh one. Set
/// `SDKWORK_ORDER_CART_SWEEP_ENABLED=false` to disable, and
/// `SDKWORK_ORDER_CART_SWEEP_INTERVAL_SECONDS` to change the cadence.
fn spawn_cart_abandonment_sweep(
    host: &Arc<OrderServiceHost>,
) -> Option<tokio::task::JoinHandle<()>> {
    if std::env::var("SDKWORK_ORDER_CART_SWEEP_ENABLED")
        .map(|value| value.trim().eq_ignore_ascii_case("false"))
        .unwrap_or(false)
    {
        return None;
    }
    let pool = match host.database_pool() {
        DatabasePool::Postgres(pool, _) => pool.clone(),
    };
    let interval_seconds = std::env::var("SDKWORK_ORDER_CART_SWEEP_INTERVAL_SECONDS")
        .ok()
        .and_then(|value| value.trim().parse::<u64>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(3600);
    let idle_days = std::env::var("SDKWORK_ORDER_CART_IDLE_DAYS")
        .ok()
        .and_then(|value| value.trim().parse::<i32>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(30);

    Some(tokio::spawn(async move {
        let mut ticker = tokio::time::interval(std::time::Duration::from_secs(interval_seconds));
        ticker.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        loop {
            ticker.tick().await;
            let store = sdkwork_order_repository_sqlx::PostgresCartStore::new(pool.clone());
            match store.expire_idle_carts(idle_days, 500).await {
                Ok(0) => {}
                Ok(expired) => {
                    tracing::info!(
                        target = "order.cart",
                        expired,
                        idle_days,
                        "expired idle buyer carts"
                    )
                }
                Err(error) => {
                    tracing::warn!(target = "order.cart", error = ?error, "cart abandonment sweep failed")
                }
            }
        }
    }))
}

fn assemble_app_api_contribution_with_host(
    host: Arc<OrderServiceHost>,
) -> Result<ApiAssemblyContribution, String> {
    let route_manifest = OrderAssemblyContract::app_route_manifest();
    let router = sdkwork_routes_order_app_api::build_order_app_business_router(host.clone());
    ApiAssemblyContribution::from_manifest(
        "sdkwork-order",
        "SDKWork Order App API",
        router,
        route_manifest,
        Vec::new(),
        Arc::new(OrderReadiness {
            pool: host.database_pool().clone(),
        }),
    )
}

/// Same as [`web_module`] but composed on a process-shared database pool
/// (platform gateways, API_ASSEMBLY_SPEC 搂4.1.1).
pub async fn web_module_with_pool(pool: DatabasePool) -> Result<WebModule, String> {
    Ok(WebModule::from_contribution(
        assemble_api_router_with_pool(pool).await?,
    ))
}
